import React from 'react';
import { BrowserRouter as Router, Route, Routes } from 'react-router-dom';
import Layout from './components/Layout';
import HomePage from './pages/HomePage';
import AboutPage from './pages/AboutPage';
import ReportsPage from './pages/ReportsPage';
import EventsPage from './pages/EventsPage';
import ResourcesPage from './pages/ResourcesPage';
import ContactPage from './pages/ContactPage';
import BudgetPage from './pages/BudgetPage';
import JoinUsPage from './pages/JoinUsPage';
import MessageOverlay from './components/MessageOverlay';
import ResearchReportDetailPage from './pages/ResearchReportDetailPage';
import EventDetailPage from './pages/EventDetailPage';
import NewsDetailPage from './pages/NewsDetailPage';

function App() {
  return (
    <Router>
      <Layout>
        <Routes>
          {/* 新聞詳細頁面路由 - 不包含 MessageOverlay */}
          <Route path="/news/:id" element={<NewsDetailPage />} />
          <Route path="/" element={<HomePage />} />

          
          {/* 其他頁面路由 - 包含 MessageOverlay */}
          <Route
            path="*"
            element={
              <MessageOverlay>
                <Routes>
                  <Route path="/about" element={<AboutPage />} />
                  <Route path="/reports" element={<ReportsPage />} />
                  <Route path="/events" element={<EventsPage />} />
                  <Route path="/resources" element={<ResourcesPage />} />
                  <Route path="/contact" element={<ContactPage />} />
                  <Route path="/budget" element={<BudgetPage />} />
                  <Route path="/get-involved" element={<JoinUsPage />} />
                  <Route path="/reports/:id" element={<ResearchReportDetailPage />} />
                  <Route path="/events/:id" element={<EventDetailPage />} />
                </Routes>
              </MessageOverlay>
            }
          />
        </Routes>
      </Layout>
    </Router>
  );
}

export default App;