import React from 'react';
import { 
  Tag, Clock, Share2, ArrowRight, ChevronRight, 
  User, MessageCircle, Bookmark, Eye, Calendar 
} from 'lucide-react';

const NewsDetail = ({ theme, newsData }) => {
  if (!newsData) return null;

  return (
    <article className={`min-h-screen ${theme === 'dark' ? 'bg-gray-900 text-gray-100' : 'bg-gray-50 text-gray-800'}`}>
      {/* 頂部大圖 */}
      <div className="relative h-[80vh] overflow-hidden">
        <div
          className="absolute inset-0 bg-cover bg-center transform scale-105 hover:scale-100 transition-transform duration-700"
          style={{
            backgroundImage: `url(${newsData.coverImage})`,
            filter: theme === 'dark' ? 'brightness(0.4)' : 'brightness(0.7)'
          }}
        />
        <div className="absolute inset-0 bg-gradient-to-b from-black/30 via-transparent to-black/80" />
        
        {/* 標題區塊 */}
        <div className="absolute bottom-0 left-0 right-0 p-8">
          <div className="container mx-auto max-w-5xl">
            {/* 分類標籤組 */}
            <div className="flex items-center gap-4 mb-8">
              {newsData.type === 'breaking' && (
                <span className="bg-red-600 px-4 py-1.5 rounded-full text-sm font-bold animate-pulse flex items-center gap-2">
                  <span className="w-2 h-2 bg-white rounded-full animate-ping"></span>
                  快訊
                </span>
              )}
              <span className="bg-purple-600/90 backdrop-blur-sm px-4 py-1.5 rounded-full text-sm font-medium">
                {newsData.department}
              </span>
            </div>

            {/* 主標題 */}
            <h1 className="text-5xl md:text-7xl font-bold mb-8 leading-tight tracking-tight text-shadow-lg text-white">
              {newsData.title}
            </h1>

            {/* 文章資訊 */}
            <div className="grid grid-cols-2 md:flex md:items-center gap-6 text-sm text-gray-200 
              border-t border-white/20 pt-6">
              <div className="flex items-center gap-2">
                <User size={18} className="text-purple-400" />
                <span>{newsData.author}</span>
              </div>
              <div className="flex items-center gap-2">
                <Calendar size={18} className="text-purple-400" />
                <span>{newsData.publishDate}</span>
              </div>
              <div className="flex items-center gap-2">
                <Eye size={18} className="text-purple-400" />
                <span>{newsData.metadata.views} 次閱讀</span>
              </div>
              <div className="flex gap-3 ml-auto">
                <button className="hover:text-purple-400 transition-colors p-2 rounded-full hover:bg-white/10">
                  <MessageCircle size={20} />
                </button>
                <button className="hover:text-purple-400 transition-colors p-2 rounded-full hover:bg-white/10">
                  <Bookmark size={20} />
                </button>
                <button className="hover:text-purple-400 transition-colors p-2 rounded-full hover:bg-white/10"
                  onClick={() => {
                    navigator.share?.({
                      title: newsData.title,
                      text: newsData.introduction,
                      url: window.location.href
                    }).catch(console.error);
                  }}
                >
                  <Share2 size={20} />
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* 主要內容區 */}
      <div className={`relative z-10 -mt-20 rounded-t-3xl overflow-hidden 
        ${theme === 'dark' ? 'bg-gray-900' : 'bg-white'} shadow-2xl`}>
        <div className="container mx-auto max-w-4xl px-4 pt-16 pb-12">
          {/* 導言區 */}
          <div className={`relative text-xl md:text-2xl leading-relaxed mb-16 
            ${theme === 'dark' ? 'text-gray-300' : 'text-gray-700'}
            pl-8 border-l-4 border-purple-600`}>
            <blockquote className="font-serif italic">
              {newsData.introduction}
            </blockquote>
          </div>

          {/* 動態目錄 */}
          <nav className={`hidden lg:block fixed left-[calc(50%+32rem)] top-1/3 w-64 p-6 rounded-lg
            ${theme === 'dark' ? 'bg-gray-800/50' : 'bg-white/50'} backdrop-blur-sm`}>
            <h4 className="text-lg font-semibold mb-4">本文章節</h4>
            <ul className="space-y-3">
              {newsData.sections.map((section, index) => (
                <li key={index}>
                  <a
                    href={`#${section.id}`}
                    className={`text-sm hover:text-purple-600 transition-colors
                      flex items-center gap-2 group`}
                  >
                    <ChevronRight size={16} className="group-hover:translate-x-1 transition-transform" />
                    {section.title}
                  </a>
                </li>
              ))}
            </ul>
          </nav>

          {/* 內文段落 */}
          <div className={`space-y-16 ${theme === 'dark' ? 'text-gray-200' : 'text-gray-800'}`}>
            {newsData.sections.map((section, index) => (
              <section key={index} className="scroll-mt-24" id={section.id}>
                <h2 className="text-3xl md:text-4xl font-bold mb-8">
                  <div className="flex items-center gap-4 group">
                    <span className="w-1.5 h-12 bg-purple-600 rounded-full
                      group-hover:h-16 transition-all"></span>
                    {section.title}
                  </div>
                </h2>
                
                {/* 內文和引述 */}
                <div className="prose prose-lg max-w-none lg:prose-xl">
                  {section.content.split(/\n\s*\n/).map((paragraph, pIndex) => {
                    // 移除段落前後的多餘空白
                    const trimmedParagraph = paragraph.trim();
                    
                    // 檢查是否為引述（以引號開始）
                    const isQuote = trimmedParagraph.startsWith('"') && trimmedParagraph.endsWith('"');
                    
                    // 檢查是否含有引號內容
                    const hasQuote = trimmedParagraph.includes('「') && trimmedParagraph.includes('」');
                    
                    if (isQuote || hasQuote) {
                      // 尋找引號中的內容
                      const quoteContent = hasQuote 
                        ? trimmedParagraph.match(/「([^」]+)」/g)
                        : null;
                        
                      if (quoteContent) {
                        // 如果找到引號內容，將其轉換為引述樣式
                        return (
                          <div key={pIndex}>
                            <p className="mb-8 leading-relaxed text-lg">
                              {trimmedParagraph.split(/「[^」]+」/).map((text, i) => (
                                <React.Fragment key={i}>
                                  {text}
                                  {quoteContent[i] && (
                                    <span className="font-medium text-lg">
                                      {quoteContent[i]}
                                    </span>
                                  )}
                                </React.Fragment>
                              ))}
                            </p>
                          </div>
                        );
                      }
                    }
                    
                    return (
                      <p key={pIndex} className="mb-8 leading-relaxed text-lg">
                        {trimmedParagraph}
                      </p>
                    );
                  })}

                  {/* 圖片區塊 */}
                  {section.image && (
                    <figure className="my-12">
                      <div className="rounded-xl overflow-hidden shadow-xl transform 
                        hover:scale-[1.02] transition-transform duration-500">
                        <img 
                          src={section.image} 
                          alt={section.title} 
                          className="w-full"
                        />
                        {section.imageCaption && (
                          <figcaption className={`p-4 text-sm
                            ${theme === 'dark' ? 'bg-gray-800 text-gray-400' : 'bg-gray-50 text-gray-600'}`}>
                            {section.imageCaption}
                          </figcaption>
                        )}
                      </div>
                    </figure>
                  )}
                </div>
              </section>
            ))}

            {/* 後續追蹤區塊 */}
            {newsData.followUp && (
              <div className={`rounded-2xl overflow-hidden shadow-lg transform hover:scale-[1.01] 
                transition-transform duration-500 ${theme === 'dark' ? 'bg-gray-800/50' : 'bg-gray-50'}`}>
                <div className="bg-gradient-to-r from-purple-600 to-purple-900 px-8 py-4">
                  <h3 className="text-2xl font-bold text-white flex items-center gap-3">
                    {newsData.followUp.title}
                  </h3>
                </div>
                <div className="p-8">
                  <p className={`mb-8 text-lg ${theme === 'dark' ? 'text-gray-300' : 'text-gray-600'}`}>
                    {newsData.followUp.description}
                  </p>
                  <ul className="space-y-4">
                    {newsData.followUp.items.map((item, index) => (
                      <li key={index} 
                        className="flex items-center group cursor-pointer 
                          hover:bg-purple-50 dark:hover:bg-gray-700/50 
                          p-3 rounded-lg transition-colors">
                        <ChevronRight size={20} 
                          className="mr-3 text-purple-600 
                          group-hover:translate-x-2 transition-transform" />
                        <span className="text-lg group-hover:text-purple-600 
                          dark:group-hover:text-purple-400 transition-colors">
                          {item}
                        </span>
                      </li>
                    ))}
                  </ul>
                </div>
              </div>
            )}

            {/* 相關標籤和分享 */}
            <div className="mt-16 pt-8 border-t border-gray-200 dark:border-gray-700">
              <div className="flex flex-wrap items-center justify-between gap-4">
                <div className="space-y-4">
                  <h4 className="text-lg font-semibold">相關標籤</h4>
                  <div className="flex flex-wrap gap-2">
                    {newsData.tags.map((tag, index) => (
                      <span
                        key={index}
                        className={`px-4 py-2 rounded-full text-sm font-medium
                          transition-all hover:scale-105 cursor-pointer
                          ${theme === 'dark' 
                            ? 'bg-gray-800 text-gray-200 hover:bg-purple-600 hover:text-white' 
                            : 'bg-gray-100 text-gray-700 hover:bg-purple-600 hover:text-white'
                          }`}
                      >
                        #{tag}
                      </span>
                    ))}
                  </div>
                </div>

                {/* 社群分享 */}
                <div className="space-y-4">
                  <h4 className="text-lg font-semibold">分享新聞</h4>
                  <div className="flex gap-2">
                    {['Facebook', 'Twitter', 'Line', 'Email'].map((platform) => (
                      <button
                        key={platform}
                        className={`p-3 rounded-full transition-all hover:scale-110
                          ${theme === 'dark' 
                            ? 'bg-gray-800 hover:bg-purple-600' 
                            : 'bg-gray-100 hover:bg-purple-600 hover:text-white'
                          }`}
                      >
                        <Share2 size={18} />
                      </button>
                    ))}
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </article>
  );
};

export default NewsDetail;