import React, { useState, useEffect } from 'react';
import { ArrowRight, AlertCircle } from 'lucide-react';

const MessageOverlay = ({ children }) => {
  const [showOverlay, setShowOverlay] = useState(false);
  const [countdown, setCountdown] = useState(30);

  useEffect(() => {
    const hasSeenMessage = localStorage.getItem('hasSeenLatestNews');
    if (!hasSeenMessage) {
      setShowOverlay(true);
    }

    if (showOverlay) {
      const timer = setInterval(() => {
        setCountdown(prevCountdown => prevCountdown - 1);
      }, 1000);

      const autoCloseTimer = setTimeout(() => {
        handleOverlayClose();
      }, 30000);

      return () => {
        clearInterval(timer);
        clearTimeout(autoCloseTimer);
      };
    }
  }, [showOverlay]);

  const handleOverlayClose = () => {
    setShowOverlay(false);
    localStorage.setItem('hasSeenLatestNews', 'true');
  };

  return (
    <>
      {showOverlay && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white p-8 rounded-lg shadow-lg max-w-2xl text-center relative mx-4">
            {/* 快訊標籤 */}
            <div className="flex items-center justify-center gap-2 mb-4">
              <AlertCircle className="text-red-600" size={20} />
              <span className="bg-red-600 text-white px-4 py-1 rounded-full text-sm font-semibold animate-pulse">
                快訊
              </span>
            </div>

            {/* 標題 */}
            <h2 className="text-2xl font-bold text-gray-800 mb-4">
              中國學生參訪團訪清大 交流會場內外行動直擊
            </h2>

            {/* 發布資訊 */}
            <div className="flex items-center justify-center gap-4 mb-4 text-sm text-gray-600">
              <span className="bg-purple-100 text-purple-700 px-3 py-1 rounded-full">
                學生會性別及人權部
              </span>
              <span>2024-12-04</span>
            </div>

            {/* 內文 */}
            <p className="text-gray-700 mb-6 text-left">
              馬英九基金會帶領中國學生參訪團來訪清大，引發校園內部討論。校內學生在名人堂外拉起「交流要平等，民主是前提」、「梅有自由，梅有交流」等標語表達訴求。交流會場內外，從主權稱謂到文化認同，呈現出複雜的兩岸交流樣貌。
            </p>

            {/* 按鈕組 */}
            <div className="flex items-center justify-center gap-4">
              <button
                onClick={handleOverlayClose}
                className="bg-gray-200 text-gray-800 px-4 py-2 rounded-full font-medium hover:bg-gray-300 transition duration-300"
              >
                稍後閱讀 ({countdown}秒)
              </button>
              <button
                onClick={() => window.location.href = '/news/20241204-china-students-visit'}
                className="bg-purple-600 text-white px-6 py-2 rounded-full font-medium hover:bg-purple-700 transition duration-300 inline-flex items-center"
              >
                立即查看 <ArrowRight size={16} className="ml-1" />
              </button>
            </div>
          </div>
        </div>
      )}
      {children}
    </>
  );
};

export default MessageOverlay;