// src/pages/NewsDetailPage.js
import React from 'react';
import { useParams, Navigate } from 'react-router-dom';
import NewsDetail from '../components/NewsDetail';
import { getNewsById } from '../data/newsData';

const NewsDetailPage = () => {
  const { id } = useParams();
  const theme = 'light'; // 或者從你的主題context獲取

  // 根據URL的id獲取對應的新聞數據
  const currentNews = getNewsById(id);

  // 如果找不到對應的新聞，重定向到首頁
  if (!currentNews) {
    return <Navigate to="/" />;
  }

  return (
    <div>
      <NewsDetail theme={theme} newsData={currentNews} />
    </div>
  );
};

export default NewsDetailPage;